PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE reports (id TEXT PRIMARY KEY, institution TEXT NOT NULL, city TEXT, copy_number TEXT, inep TEXT, client_name TEXT, phone TEXT, function_name TEXT NOT NULL, version TEXT, system_path TEXT NOT NULL, description TEXT NOT NULL, school_year TEXT, urgent INTEGER NOT NULL DEFAULT 0, beta_status TEXT NOT NULL DEFAULT 'Não testado', workaround TEXT, from_test_round INTEGER NOT NULL DEFAULT 0, test_round_id TEXT, test_round_title TEXT, test_round_version TEXT, test_item_id TEXT, test_item_title TEXT, status TEXT NOT NULL DEFAULT 'Novo report', author_id TEXT NOT NULL, author_email TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE attachments (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, object_key TEXT NOT NULL UNIQUE, file_name TEXT NOT NULL, content_type TEXT NOT NULL, byte_size INTEGER NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE activities (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, actor_id TEXT NOT NULL, actor_email TEXT NOT NULL, action TEXT NOT NULL, message TEXT, created_at INTEGER NOT NULL);
CREATE TABLE report_shares (report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, user_email TEXT NOT NULL, permission TEXT NOT NULL DEFAULT 'edit', shared_by_id TEXT NOT NULL, shared_by_email TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (report_id, user_email));
CREATE TABLE test_rounds (id TEXT PRIMARY KEY, title TEXT NOT NULL, version TEXT NOT NULL, deadline TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'Em andamento', author_id TEXT NOT NULL, author_email TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, tags TEXT NOT NULL DEFAULT '[]');
CREATE TABLE test_items (id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES test_rounds(id) ON DELETE CASCADE, position INTEGER NOT NULL, title TEXT NOT NULL, path TEXT, description TEXT, status TEXT NOT NULL DEFAULT 'Pendente', tester_id TEXT, tester_email TEXT, result_note TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE round_participants (round_id TEXT NOT NULL REFERENCES test_rounds(id) ON DELETE CASCADE, user_id TEXT NOT NULL, user_email TEXT NOT NULL, user_name TEXT NOT NULL, joined_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, completed_at INTEGER, `deadline_override` text, PRIMARY KEY (round_id, user_id));
CREATE TABLE test_item_responses (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES test_items(id) ON DELETE CASCADE, round_id TEXT NOT NULL REFERENCES test_rounds(id) ON DELETE CASCADE, tester_id TEXT NOT NULL, tester_email TEXT NOT NULL, tester_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pendente', result_note TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE (item_id, tester_id));
ANALYZE sqlite_schema;
CREATE TABLE team_members (email TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'support' CHECK(role IN ('support','manager','developer')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_reports_status_updated_at ON reports(status, updated_at);
CREATE INDEX idx_reports_version ON reports(version);
CREATE INDEX idx_attachments_report_id ON attachments(report_id);
CREATE INDEX idx_activities_report_created_at ON activities(report_id, created_at);
CREATE INDEX idx_report_shares_email ON report_shares(user_email, report_id);
CREATE INDEX idx_test_rounds_status_updated_at ON test_rounds(status, updated_at);
CREATE INDEX idx_test_items_round_position ON test_items(round_id, position);
CREATE INDEX idx_round_participants_round ON round_participants(round_id, updated_at);
CREATE INDEX idx_test_responses_round_tester ON test_item_responses(round_id, tester_id, status);
CREATE INDEX idx_team_members_role ON team_members(role, email);
